/// Classic phase vocoder with optional identity phase locking
/// (Laroche-Dolson).
///
/// Rust: `audio::vocoder::PhaseVocoder`
#[pyclass(name = "PhaseVocoder", module = "rust_physics_engine.audio.vocoder")]
pub struct PyPhaseVocoder { pub inner: rust_physics_engine::audio::vocoder::PhaseVocoder }
#[pymethods]
impl PyPhaseVocoder {
    /// New vocoder with the given FFT size and (synthesis) hop.
    ///
    /// Rust: `audio::vocoder::PhaseVocoder::new`
    #[new]
    #[pyo3(signature = (n_fft, hop, fs))]
    fn __new__(n_fft: usize, hop: usize, fs: f64) -> PyResult<crate::generated::types::PyPhaseVocoder> {
        let __r = crate::runtime::guard(|| rust_physics_engine::audio::vocoder::PhaseVocoder::new(n_fft, hop, fs));
        let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
        Ok(crate::generated::types::PyPhaseVocoder { inner: __v })
    }

    /// Enable/disable identity phase locking (phases of non-peak bins
    /// follow their nearest spectral peak).
    ///
    /// Rust: `audio::vocoder::PhaseVocoder::phase_lock`
    #[pyo3(name = "phase_lock")]
    #[pyo3(signature = (on))]
    fn phase_lock(&mut self, on: bool) -> PyResult<()> {
        let __r = crate::runtime::guard(|| self.inner.phase_lock(on));
        let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
        Ok(())
    }

    /// Time-stretch by `ratio` (>1 = longer) without changing pitch.
    ///
    /// Rust: `audio::vocoder::PhaseVocoder::time_stretch`
    #[pyo3(name = "time_stretch")]
    #[pyo3(signature = (x, ratio))]
    fn time_stretch<'py>(&mut self, py: Python<'py>, x: Vec<f64>, ratio: f64) -> PyResult<Vec<f64>> {
        let __r = py.detach(move || crate::runtime::guard(move || self.inner.time_stretch(&x, ratio)));
        let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
        Ok(__v)
    }

    /// Pitch-shift by `semitones` keeping the duration (stretch then
    /// resample).
    ///
    /// Rust: `audio::vocoder::PhaseVocoder::pitch_shift`
    #[pyo3(name = "pitch_shift")]
    #[pyo3(signature = (x, semitones))]
    fn pitch_shift<'py>(&mut self, py: Python<'py>, x: Vec<f64>, semitones: f64) -> PyResult<Vec<f64>> {
        let __r = py.detach(move || crate::runtime::guard(move || self.inner.pitch_shift(&x, semitones)));
        let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
        Ok(__v)
    }

    /// Pitch shift with spectral-envelope (formant) preservation: the
    /// shifted signal is re-filtered toward the original envelope.
    ///
    /// Rust: `audio::vocoder::PhaseVocoder::pitch_shift_formant_preserving`
    #[pyo3(name = "pitch_shift_formant_preserving")]
    #[pyo3(signature = (x, semitones))]
    fn pitch_shift_formant_preserving<'py>(&mut self, py: Python<'py>, x: Vec<f64>, semitones: f64) -> PyResult<Vec<f64>> {
        let __r = py.detach(move || crate::runtime::guard(move || self.inner.pitch_shift_formant_preserving(&x, semitones)));
        let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
        Ok(__v)
    }

    /// Loop the spectral frame at `at_sample` for `duration` samples.
    ///
    /// Rust: `audio::vocoder::PhaseVocoder::freeze`
    #[pyo3(name = "freeze")]
    #[pyo3(signature = (x, at_sample, duration))]
    fn freeze<'py>(&mut self, py: Python<'py>, x: Vec<f64>, at_sample: usize, duration: usize) -> PyResult<Vec<f64>> {
        let __r = py.detach(move || crate::runtime::guard(move || self.inner.freeze(&x, at_sample, duration)));
        let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
        Ok(__v)
    }

    /// Zero every phase: monotone "robot" voice at the frame rate.
    ///
    /// Rust: `audio::vocoder::PhaseVocoder::robotize`
    #[pyo3(name = "robotize")]
    #[pyo3(signature = (x))]
    fn robotize<'py>(&mut self, py: Python<'py>, x: Vec<f64>) -> PyResult<Vec<f64>> {
        let __r = py.detach(move || crate::runtime::guard(move || self.inner.robotize(&x)));
        let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
        Ok(__v)
    }

    /// Randomize every phase: breathy "whisper" voice.
    ///
    /// Rust: `audio::vocoder::PhaseVocoder::whisperize`
    #[pyo3(name = "whisperize")]
    #[pyo3(signature = (x))]
    fn whisperize<'py>(&mut self, py: Python<'py>, x: Vec<f64>) -> PyResult<Vec<f64>> {
        let __r = py.detach(move || crate::runtime::guard(move || self.inner.whisperize(&x)));
        let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
        Ok(__v)
    }

    fn __repr__(&self) -> String { "<PhaseVocoder>".to_string() }
}

/// Decoded audio: sample rate, channel count, and per-channel samples
/// in −1..1.
///
/// Rust: `audio::wav::WavData`
